import{_ as o,o as t,c as r,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const g=JSON.parse('{"title":"Troubleshooting: Credits & Billing","description":"Understand your token consumption, resolve overdraft blocks, and troubleshoot Basic/Pro tier issues.","frontmatter":{"title":"Troubleshooting: Credits & Billing","description":"Understand your token consumption, resolve overdraft blocks, and troubleshoot Basic/Pro tier issues."},"headers":[],"relativePath":"support/troubleshooting_credits.md","filePath":"support/troubleshooting_credits.md"}'),s={name:"support/troubleshooting_credits.md"};function a(n,e,l,u,d,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="troubleshooting-credits-billing" tabindex="-1">Troubleshooting: Credits &amp; Billing <a class="header-anchor" href="#troubleshooting-credits-billing" aria-label="Permalink to &quot;Troubleshooting: Credits &amp; Billing&quot;">​</a></h1><p>Sanjeev AI operates on a dual-model billing system using <strong>Tiers</strong> (Basic vs Pro) and <strong>Credits</strong> (pay-as-you-go).</p><h2 id="_1-resource-exhausted-error" tabindex="-1">1. &quot;RESOURCE_EXHAUSTED&quot; Error <a class="header-anchor" href="#_1-resource-exhausted-error" aria-label="Permalink to &quot;1. &quot;RESOURCE_EXHAUSTED&quot; Error&quot;">​</a></h2><p><strong>Symptom:</strong> AI generation steps (audio, visuals, orchestrator) fail with a <code>RESOURCE_EXHAUSTED</code> error. <strong>Cause:</strong> Your credit balance has reached the strict overdraft limit (-5000 credits). <strong>Solution:</strong></p><ul><li>Visit the <strong>Usage Dashboard</strong> to check your current balance.</li><li>You must purchase a credit top-up to resume AI generation.</li><li>Note: Even on the Pro tier, image and video generation consume credits. Pro tier grants a monthly allowance, but heavy usage may require additional top-ups.</li></ul><h2 id="_2-unexplained-credit-deductions" tabindex="-1">2. Unexplained Credit Deductions <a class="header-anchor" href="#_2-unexplained-credit-deductions" aria-label="Permalink to &quot;2. Unexplained Credit Deductions&quot;">​</a></h2><p><strong>Symptom:</strong> You notice your credit balance dropping faster than expected. <strong>Cause:</strong> Video loop generation (Veo) and Cloud Video Rendering (FFmpeg) are the most expensive operations. Additionally, running the AI Parser on massive scripts consumes Gemini tokens. <strong>Solution:</strong></p><ol><li>Navigate to the <strong>Audit Ledger</strong> at the bottom of the Usage page.</li><li>The ledger provides an immutable, line-by-line receipt for every action.</li><li>Check the <code>metric</code> column to see which specific service (e.g., <code>veo-3.1-generate</code>, <code>imagen-3.0-generate</code>) caused the deduction.</li></ol><h2 id="_3-basic-tier-features-showing-for-pro-users" tabindex="-1">3. Basic Tier Features Showing for Pro Users <a class="header-anchor" href="#_3-basic-tier-features-showing-for-pro-users" aria-label="Permalink to &quot;3. Basic Tier Features Showing for Pro Users&quot;">​</a></h2><p><strong>Symptom:</strong> You paid for the Pro tier, but the &quot;Cloud Render&quot; option is still disabled, or you still see upgrade prompts. <strong>Cause:</strong> Your client-side Firebase Auth token has cached your old &quot;Basic&quot; plan claim. <strong>Solution:</strong></p><ol><li>Log out of Sanjeev AI.</li><li>Log back in to force your browser to fetch the latest Custom Claims from Firebase.</li><li>If it still fails, check your payment status in the billing portal to ensure the subscription was successful.</li></ol><h2 id="_4-the-overdraft-buffer" tabindex="-1">4. The Overdraft Buffer <a class="header-anchor" href="#_4-the-overdraft-buffer" aria-label="Permalink to &quot;4. The Overdraft Buffer&quot;">​</a></h2><p>Sanjeev AI employs an &quot;Overdraft Buffer&quot;. If you have 50 credits left, but request a video generation that costs 500 credits, we will allow the operation to succeed, pushing your balance to -450. You will only be blocked from <em>subsequent</em> requests once your balance falls below -5000.</p>',13)])])}const p=o(s,[["render",a]]);export{g as __pageData,p as default};
